'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var isUint64 = require( '@stdlib/assert/is-uint64' );
var isEqual = require( '@stdlib/number/uint64/base/assert/is-equal' );
var add = require( '@stdlib/number/uint64/base/add' );
var Number = require( '@stdlib/number/ctor' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var Uint64Array = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Uint64Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the prototype of the main export is a `reduce` method', function test( t ) {
	t.strictEqual( hasOwnProp( Uint64Array.prototype, 'reduce' ), true, 'has property' );
	t.strictEqual( isFunction( Uint64Array.prototype.reduce ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a 64-bit unsigned integer array instance', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Uint64Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.reduce.call( value, add );
		};
	}
});

tape( 'the method throws an error if provided a first argument which is not a function', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Uint64Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.reduce( value );
		};
	}
});

tape( 'the method throws an error if not provided an initial value when operating on an empty 64-bit unsigned integer array', function test( t ) {
	var arr;

	arr = new Uint64Array( 0 );
	t.throws( foo, Error, 'throws an error' );
	t.end();

	function foo() {
		arr.reduce( add );
	}
});

tape( 'the method uses the first element of the array as the initial value when an initial value is not provided', function test( t ) {
	var valueArray;
	var accArray;
	var expected;
	var actual;
	var arr;

	arr = new Uint64Array( [ 1, 2, 3 ] );
	accArray = [ 1, 3 ];
	valueArray = [ 2, 3 ];
	expected = new Uint64( 6 );
	actual = arr.reduce( reducer );

	t.strictEqual( isUint64( actual ), true, 'returns expected value' );
	t.strictEqual( isEqual( actual, expected ), true, 'returns expected value' );

	t.end();

	function reducer( acc, value, index ) {
		var ind = index - 1;
		t.strictEqual( isUint64( acc ), true, 'returns expected value' );
		t.strictEqual( isEqual( acc, new Uint64( accArray[ ind ] ) ), true, 'returns expected value' );
		t.strictEqual( isUint64( value ), true, 'returns expected value' );
		t.strictEqual( isEqual( value, new Uint64( valueArray[ ind ] ) ), true, 'returns expected value' );
		return add( acc, value );
	}
});

tape( 'the method supports providing an initial value as the second argument', function test( t ) {
	var valueArray;
	var accArray;
	var expected;
	var actual;
	var arr;

	arr = new Uint64Array( [ 1, 2, 3 ] );
	accArray = [ 2, 3, 5 ];
	valueArray = [ 1, 2, 3 ];
	expected = new Uint64( 8 );
	actual = arr.reduce( reducer, new Uint64( 2 ) );

	t.strictEqual( isUint64( actual ), true, 'returns expected value' );
	t.strictEqual( isEqual( actual, expected ), true, 'returns expected value' );

	t.end();

	function reducer( acc, value, index ) {
		t.strictEqual( isUint64( acc ), true, 'returns expected value' );
		t.strictEqual( isEqual( acc, new Uint64( accArray[ index ] ) ), true, 'returns expected value' );
		t.strictEqual( isUint64( value ), true, 'returns expected value' );
		t.strictEqual( isEqual( value, new Uint64( valueArray[ index ] ) ), true, 'returns expected value' );
		return add( acc, value );
	}
});

tape( 'the method returns the accumulated result', function test( t ) {
	var expected;
	var actual;
	var arr;

	arr = new Uint64Array( [ 1, 2, 3 ] );
	expected = new Uint64( 6 );
	actual = arr.reduce( add );

	t.strictEqual( isUint64( actual ), true, 'returns expected value' );
	t.strictEqual( isEqual( actual, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the method supports returning real-valued results', function test( t ) {
	var expected;
	var actual;
	var arr;

	arr = new Uint64Array( [ 1, 2, 3 ] );
	expected = 6;
	actual = arr.reduce( reducer, 0 );

	t.strictEqual( actual, expected, 'returns expected value' );
	t.end();

	function reducer( acc, value ) {
		return acc + Number( value );
	}
});
